import { loadConversation } from "../redux/execution-system/thunks/load-conversation.thunk.js";
import { followWhatIsStillInFlight } from "./follow-what-is-still-in-flight.js";
import { markAnswerFollowing } from "./mark-answer-following.js";
async function rereadAndFollow(dispatch, conversationId, label) {
  dispatch(markAnswerFollowing(conversationId));
  try {
    await dispatch(loadConversation({ conversationId })).unwrap();
  } catch (err) {
    console.warn(
      `[${label}] re-reading the conversation failed \u2014 following the live turn anyway; the rows show on the next load.`,
      err
    );
  }
  followWhatIsStillInFlight(dispatch, conversationId);
}
export {
  rereadAndFollow
};
